// Launch Params: the launch row is the contract: Client (resolves the base), Table (People), View
// (optional: the machine filters Status = verifying itself, so no view means the whole table).
const rec=$('Fetch Launch Record').first().json||{};
const f=rec.fields||{};
const cf=(($('Resolve Base').first().json||{}).fields)||{};
const base=String(cf['Clayroots Base ID']||'').trim();
const arr=(v)=>Array.isArray(v)?v:(v==null||v===''?[]:[v]);
const clientRecId=(arr(f['Client']).map(x=>(x&&typeof x==='object')?x.id:x)[0])||'';
const table=String(f['Table']||'People').trim();
const where='Launch record '+(rec.id||'?');
if(!clientRecId) throw new Error(where+' has no Client link. Nothing was verified.');
if(!/^app[A-Za-z0-9]{14}$/.test(base)) throw new Error('Client on '+where.toLowerCase()+' has no valid Clayroots Base ID. Nothing was verified.');
if(table.toLowerCase()!=='people') throw new Error(where+' names Table "'+table+'". Verify Catch-alls runs on People. Nothing was verified.');
return [{ json:{ base, clientRecId, table:'People', view:String(f['View']||'').trim(), trigger:'form', _launchRecordId:rec.id||'', parentExecId:'', startedAt:new Date().toISOString() } }];

// Event Params: the sub-workflow entry. Enrich Emails fires it after its last batch with the table
// and view it worked; the hourly schedule fires it once per client with the whole People table.
const j=$input.first().json||{};
const base=String(j.base||j.baseId||'').trim();
if(!/^app[A-Za-z0-9]{14}$/.test(base)) throw new Error('Verify Catch-alls was called without a valid base. Nothing was verified.');
return [{ json:{ base, clientRecId:String(j.clientRecId||j.clientRecordId||'').trim(), table:'People', view:String(j.view||'').trim(), trigger:j.trigger==='schedule'?'schedule':'event', _launchRecordId:'', parentExecId:String(j.parentExecId||''), startedAt:new Date().toISOString() } }];

// Fan Out: the hourly schedule serves every client. One item per Clients row that carries a
// Clayroots Base ID; each becomes its own run of this machine (Run Per Client, not awaited) with
// the whole People table, so every client's row is its own and a slow one never blocks another.
const out=[];
for(const it of $input.all()){ const j=it.json||{}; const f=j.fields||{}; const base=String(f['Clayroots Base ID']||'').trim(); if(!/^app[A-Za-z0-9]{14}$/.test(base)) continue; out.push({ json:{ base, clientRecId:j.id, client:String(f.Client||''), table:'People', view:'', trigger:'schedule', parentExecId:String($execution.id) } }); }
if(!out.length) return [{ json:{ _empty:true } }];
return out;

// Fan Out Log: the schedule's own heartbeat row: which clients were fired. Each client run writes
// its own row keyed on its execution.
const fired=$('Fan Out').all().map(i=>i.json||{}).filter(j=>!j._empty);
const lines=['**Hourly sweep: '+fired.length+' client run'+(fired.length===1?'':'s')+' fired (each writes its own row)**','','**Scope:** every client with a Clayroots Base ID; each run reads People with Status = verifying'];
for(const f of fired) lines.push('- '+(f.client||f.clientRecId)+' ('+f.base+')');
if(!fired.length) lines.push('','**Skipped (no client carries a Clayroots Base ID)**');
return [{ json:{ 'Execution ID':String($execution.id), 'Automation':'Verify Catch-alls', 'Status':'Succeeded', 'Trigger':'schedule', 'Errors':0, 'Run at':new Date().toISOString(), 'Records In':fired.length, 'Records Out':fired.length, 'Description':lines.join('\n'), 'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id } }];

// Params: one shape for both entries.
let p=null;
try{ p=$('Launch Params').first().json; }catch(e){}
if(!p||!p.base){ try{ p=$('Event Params').first().json; }catch(e){} }
if(!p||!p.base) throw new Error('Verify Catch-alls: no entry produced parameters.');
return [{ json:p }];

// Resolve Table: People by name in the base meta; the view by name or id when one was given, else
// the table's first view (the whole table). Field names and types travel for the requirements check.
const p=$('Params').first().json;
const r=$input.first().json||{}; const body=(r.body!==undefined)?r.body:r;
const tables=(body&&Array.isArray(body.tables))?body.tables:null;
if(!tables) throw new Error('Could not read the table list for base '+p.base+': '+JSON.stringify(body).slice(0,200)+'. Nothing was verified.');
const t=tables.find(x=>String(x.name||'').trim().toLowerCase()==='people');
if(!t) throw new Error('Base '+p.base+' has no People table. Nothing was verified.');
let v=null;
if(p.view){ v=(t.views||[]).find(x=>x.id===p.view||String(x.name||'').trim()===p.view); if(!v) throw new Error('People ('+t.id+') in base '+p.base+' has no view "'+p.view+'". Nothing was verified.'); }
else v=(t.views||[])[0]||null;
if(!v) throw new Error('People ('+t.id+') in base '+p.base+' has no views at all.');
const types={}; for(const f of (t.fields||[])) types[f.name]=f.type;
return [{ json:{ tableId:t.id, tableName:t.name, viewId:v.id, viewName:p.view?v.name:'(whole table)', fieldNames:(t.fields||[]).map(f=>f.name), fieldTypes:types } }];

// Check Columns: requirements (Status, Email, first_name, last_name, Domain) must exist; the
// fields shared with Enrich Emails (Final Email, Email Provider, Email Verified By, Email Verified
// At, Email Candidates) are created here on first use when the base lacks them, the same
// definitions as Enrich Emails declares.
const p=$('Params').first().json;
const t=$('Resolve Table').first().json;
const have=new Set(t.fieldNames||[]);
const REQUIRED=['Status','Email','first_name','last_name','Domain'];
const missing=REQUIRED.filter(n=>!have.has(n));
if(missing.length) throw new Error('People ('+t.tableId+') in base '+p.base+' is missing '+missing.join(', ')+'. Nothing was verified.');
const OWN=[
  { name:'Final Email', type:'singleLineText' },
  { name:'Email Provider', type:'singleSelect', options:{ choices:[{name:'database',color:'blueLight2'},{name:'pattern',color:'cyanLight2'},{name:'Blitz',color:'tealLight2'},{name:'LeadMagic',color:'purpleLight2'}] } },
  { name:'Email Verified By', type:'singleSelect', options:{ choices:[{name:'MillionVerifier',color:'greenLight2'},{name:'BounceBan',color:'yellowLight2'}] } },
  { name:'Email Verified At', type:'dateTime', options:{ dateFormat:{name:'iso'}, timeFormat:{name:'24hour'}, timeZone:'utc' } },
  { name:'Email Candidates', type:'singleLineText' }
];
const toCreate=OWN.filter(f=>!have.has(f.name));
const url='https://api.airtable.com/v0/meta/bases/'+p.base+'/tables/'+t.tableId+'/fields';
return [{ json:{ base:p.base, tableId:t.tableId, toCreate:toCreate.map(f=>f.name), creates:toCreate.map(f=>({ url:url, body:f })) } }];

// Plan Columns: one meta-API call per own field the table lacks.
const c=$('Check Columns').first().json;
return (c.creates||[]).map(x=>({ json:x }));

// Verify Columns: the base meta read again after the creates; anything still missing stops the run.
const c=$('Check Columns').first().json;
const r=$input.first().json||{}; const body=(r.body!==undefined)?r.body:r;
const tables=(body&&Array.isArray(body.tables))?body.tables:null;
if(!tables) throw new Error('Could not re-read the table list for base '+c.base+' after creating columns.');
const names=new Set((((tables.find(t=>t.id===c.tableId))||{}).fields||[]).map(f=>f.name));
const still=(c.toCreate||[]).filter(n=>!names.has(n));
if(still.length) throw new Error('Verify Catch-alls created columns the base does not show: '+still.join(', ')+'.');
return [{ json:{ created:c.toCreate.slice() } }];

// Plan: every row Status = verifying in the read -> up to three BounceBan submissions per row, in
// priority order. The candidates come from Email Candidates ("email|origin, ...", written by Enrich
// Emails); a row without it (an older row, or one marked by hand) falls back to the Email cell with
// origin database. One item per address; the row's position order decides which deliverable wins.
const rows=$input.all().map(i=>i.json||{}).filter(j=>j.id);
const clean=(s)=>String(s||'').trim().toLowerCase();
const isEmail=(e)=>/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e);
const out=[]; let rowsIn=0, noCandidates=0;
for(const r of rows){
  const f=r.fields||{};
  if(String(f.Status||'')!=='verifying') continue;
  rowsIn++;
  let cands=String(f['Email Candidates']||'').split(',').map(s=>s.trim()).filter(Boolean).map(s=>{ const p=s.split('|'); return { email:clean(p[0]), origin:(p[1]||'database').trim() }; }).filter(c=>isEmail(c.email));
  if(!cands.length) cands=String(f.Email||'').split(/[,;\s]+/).map(clean).filter(isEmail).map(e=>({ email:e, origin:'database' }));
  const seen=new Set(); cands=cands.filter(c=>{ if(seen.has(c.email)) return false; seen.add(c.email); return true; }).slice(0,3);
  if(!cands.length){ noCandidates++; out.push({ json:{ rowId:r.id, email:'', origin:'', pos:0, _none:true } }); continue; }
  cands.forEach((c,i)=>out.push({ json:{ rowId:r.id, email:c.email, origin:c.origin, pos:i } }));
}
if(!out.length) return [{ json:{ _empty:true, _stats:{ rowsIn, noCandidates } } }];
out[0].json._stats={ rowsIn, noCandidates, submissions:out.filter(x=>!x.json._none).length };
return out;

// Submit Requests: only the addresses to submit (rows with no candidate carry nothing to BounceBan
// and settle as no_email_found in the verdict).
const items=$input.all().map(i=>i.json||{}).filter(j=>!j._empty&&!j._none&&j.email);
if(!items.length) return [{ json:{ _none:true } }];
return items.map(j=>({ json:{ rowId:j.rowId, email:j.email, origin:j.origin, pos:j.pos } }));

// Init: the submit answers (aligned to Submit Requests) with BounceBan's verification id attached;
// an address BounceBan refused carries no id and is written as an error in the verdict.
const reqs=$('Submit Requests').all().map(i=>i.json||{}).filter(j=>!j._none);
const t0=Date.now();
return $input.all().map((it,i)=>{ const q=reqs[i]||{}; const r=it.json||{}; return { json:{ rowId:q.rowId, email:q.email, origin:q.origin, pos:q.pos, id:(r&&r.id)?String(r.id):'', result:'', _t0:t0, _submitErr:(r&&r.id)?'':String((r&&(r.message||r.error))||'no id in the answer').slice(0,120) } }; });

// Gate: the poll answers (one per Init item, aligned by index; every item is polled every round,
// the proven poller shape) folded onto the carriers from Init. Loop while any submitted address has
// no verdict and the 60-minute cap has not passed; the wait grows 15, 30, 60, 180 s. An address
// with no verdict at the cap keeps result '' (the row stays verifying for the next sweep).
const BBOK=['deliverable','undeliverable','risky','unknown'];
const base=$('Init').all().map(i=>i.json||{});
const polls=$input.all().map(i=>i.json||{});
const t0=Number((base[0]||{})._t0)||Date.now();
const elapsed=Date.now()-t0;
const MAX=3600000;
const out=base.map((c,idx)=>{ const j=polls[idx]||{}; const res=(c.id&&BBOK.indexOf(j.result)>-1)?j.result:''; return Object.assign({},c,{ result:res }); });
const anyPending=out.some(c=>c.id&&!c.result)&&elapsed<MAX;
const w=elapsed<30000?15:elapsed<120000?30:elapsed<300000?60:180;
return out.map(c=>({ json:Object.assign({},c,{ _loop:anyPending, _nextWaitSec:w, _elapsedS:Math.round(elapsed/1000) }) }));

// Verdict: per row, the first candidate by position that BounceBan called deliverable wins: Final
// Email, Email Provider = its origin, Email Verified By BounceBan, Email Verified At, Status done,
// Email Candidates cleared. Every candidate undeliverable or risky or unknown: no_email_found
// (risky is not deployable). Any candidate still without a verdict at the cap: nothing written,
// the row stays verifying for the next sweep. A row with no candidate at all: no_email_found.
const now=new Date().toISOString();
const settled=$input.all().map(i=>i.json||{});
let planned=[]; try{ planned=$('Plan').all().map(i=>i.json||{}).filter(j=>!j._empty); }catch(e){}
const byRow={};
for(const p of planned){ const r=byRow[p.rowId]||(byRow[p.rowId]={ cands:[], none:!!p._none }); if(!p._none) r.cands.push({ email:p.email, origin:p.origin, pos:p.pos, result:'', id:'' }); }
for(const s of settled){ const r=byRow[s.rowId]; if(!r) continue; const c=r.cands.find(x=>x.email===s.email); if(c){ c.result=s.result||''; c.id=s.id||''; c.submitErr=s._submitErr||''; } }
const out=[]; const st={ rows:0, done:0, noEmail:0, pending:0, byProvider:{}, submitted:0, refused:0, verdicts:{} };
for(const id of Object.keys(byRow)){
  const r=byRow[id]; st.rows++;
  if(r.none||!r.cands.length){ out.push({ json:{ id, 'Status':'no_email_found', 'Email Candidates':'' } }); st.noEmail++; continue; }
  r.cands.sort((a,b)=>a.pos-b.pos);
  for(const c of r.cands){ if(c.id) st.submitted++; else st.refused++; if(c.result) st.verdicts[c.result]=(st.verdicts[c.result]||0)+1; }
  const win=r.cands.find(c=>c.result==='deliverable');
  if(win){ out.push({ json:{ id, 'Final Email':win.email, 'Email Provider':win.origin, 'Email Verified By':'BounceBan', 'Email Verified At':now, 'Status':'done', 'Email Candidates':'' } }); st.done++; st.byProvider[win.origin]=(st.byProvider[win.origin]||0)+1; continue; }
  const open=r.cands.some(c=>c.id&&!c.result);
  if(open){ st.pending++; continue; }
  out.push({ json:{ id, 'Status':'no_email_found', 'Email Candidates':'' } }); st.noEmail++;
}
if(!out.length) return [{ json:{ _empty:true, _stats:st } }];
out[0].json._stats=st;
return out;

// Chunk Rows: the verdict rows in tens, one item per Airtable request, PATCHed as {records:[{id,
// fields}], typecast:true} 200 ms apart (typecast lets a new provider's name mint its choice on
// Email Provider). Ids and size ride on the item for the count-back; carriers are stripped.
const rows=$input.all().map(i=>i.json).filter(j=>j&&j.id&&!j._empty);
const out=[];
for(let i=0;i<rows.length;i+=10){
  const part=rows.slice(i,i+10);
  out.push({ json:{ body:{ records:part.map(r=>{ const f={}; for(const k of Object.keys(r)){ if(k!=='id'&&k.charAt(0)!=='_') f[k]=r[k]; } return { id:String(r.id), fields:f }; }), typecast:true }, ids:part.map(r=>String(r.id)), size:part.length } });
}
return out;

// Write Check: the writer's count-back. Written rows are counted from every 2xx answer's records[];
// a request that was not 2xx counts every row it carried as a write error and names the ids. The
// writer never retries (a 429 locks the base for 30 s). Exactly one item out.
const n=(v)=>Number(v)||0;
const parse=(b)=>{ if(typeof b!=='string') return b; try{ return JSON.parse(b); }catch(e){ return null; } };
let chunks=[], resps=[];
try{ chunks=$('Chunk Rows').all().map(i=>i.json); }catch(e){}
try{ resps=$('Write Rows').all(); }catch(e){}
let written=0, writeErrors=0; const failed=[], reasons=[];
const note=(ids,why)=>{ for(const id of (ids||[])){ if(failed.length<200) failed.push(id); } const w=String(why||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().slice(0,180); if(w&&reasons.length<10) reasons.push(w); };
resps.forEach((it,i)=>{
  const c=chunks[i]||{ size:0, ids:[] }; const j=it.json||{};
  if(j.error&&j.statusCode===undefined){ writeErrors+=n(c.size); note(c.ids,'row writer: '+String((j.error&&j.error.message)||j.error||'call failed')); return; }
  const status=n(j.statusCode); const b=parse(j.body===undefined?null:j.body);
  if(status>=200&&status<300&&b&&Array.isArray(b.records)){ written+=b.records.length; if(b.records.length<n(c.size)){ const back={}; for(const r of b.records) back[String((r||{}).id||'')]=1; writeErrors+=n(c.size)-b.records.length; note((c.ids||[]).filter(id=>!back[id]),(n(c.size)-b.records.length)+' of '+c.size+' records missing from a 2xx answer'); } return; }
  const e=b&&b.error; const why=e?(typeof e==='object'?(e.message||e.type||JSON.stringify(e)):String(e)):((j.error&&j.error.message)||(typeof j.body==='string'?j.body:''));
  writeErrors+=n(c.size); note(c.ids,'HTTP '+status+' '+String(why||'')+(status===429?' (rate limited; never retried)':''));
});
return [{ json:{ written, writeErrors, writeRequests:resps.length, failed, writeReasons:reasons } }];

// Build Log: this run's Hub row. A launched run updates its launch row; an event run (fired by Enrich
// Emails, or by the hourly fan-out) is keyed "<caller execution>-verify" so it reads as a detail row
// under the run it belongs to. Status computed; a candidate BounceBan refused at submit is an error,
// a row still pending at the cap is a skip (the next sweep takes it).
const p=$('Params').first().json;
let t={}; try{ t=$('Resolve Table').first().json||{}; }catch(e){}
let planned={}; try{ const j=$('Plan').first().json||{}; planned=j._stats||{}; }catch(e){}
let st={ rows:0, done:0, noEmail:0, pending:0, byProvider:{}, submitted:0, refused:0, verdicts:{} };
try{ const j=$('Verdict').first().json||{}; if(j._stats) st=Object.assign(st,j._stats); }catch(e){}
let wc={ written:0, writeErrors:0, writeReasons:[] }; try{ wc=Object.assign(wc,$('Write Check').first().json||{}); }catch(e){}
let elapsed=0; try{ elapsed=Number($('Gate').last().json._elapsedS)||0; }catch(e){}
const n=(v)=>Number(v)||0;
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(p.startedAt).getTime())/1000)); }catch(e){}
const failed=n(st.refused)+n(wc.writeErrors);
const prov=Object.entries(st.byProvider||{}).map(([k,v])=>k+' '+v).join(', ')||'none';
const verd=Object.entries(st.verdicts||{}).map(([k,v])=>k+' '+v).join(', ')||'none';
const lines=[
  '**'+n(st.rows)+' catch-all people, '+n(st.done)+' resolved by BounceBan, '+n(st.noEmail)+' no deliverable address, '+n(st.pending)+' still waiting**',
  '',
  '**Scope:** one client, People '+(t.viewName||'(whole table)')+', rows with Status = verifying'+(p.parentExecId?', fired by run '+p.parentExecId:''),
  '**Rule:** up to three candidates per person submitted to BounceBan at once (Email Candidates, priority order); the first deliverable wins; risky and unknown are not deployable; a verdict missing at the 60-minute cap leaves the row verifying for the hourly sweep.',
  '',
  '**Results**',
  '- **Submitted:** '+n(st.submitted)+' addresses'+(n(st.refused)?', '+n(st.refused)+' refused at submit':''),
  '- **Verdicts:** '+verd,
  '- **Resolved by provider:** '+prov,
  '- **Rows written (confirmed by Airtable):** '+n(wc.written)+(n(wc.writeErrors)?', '+n(wc.writeErrors)+' refused':''),
  '- **Polling:** '+elapsed+' s'
];
if(!n(st.rows)) lines.push('', '**Skipped (no row with Status = verifying)**');
if(n(st.pending)) lines.push('', '**Skipped ('+n(st.pending)+' rows still without a verdict at the cap; the hourly sweep takes them)**');
if((wc.writeReasons||[]).length){ lines.push('', '**Write failures**'); for(const w of wc.writeReasons.slice(0,10)) lines.push('- '+w); }
const key=p._launchRecordId?String($execution.id):((p.parentExecId||String($execution.id))+'-verify');
const log={ 'Execution ID':key, 'Automation':'Verify Catch-alls', 'Status':failed?'Succeeded with errors':'Succeeded', 'Trigger':p.trigger||'event', 'Errors':failed, 'Run at':p.startedAt, 'Target':(t.tableName||'People')+' ('+(t.tableId||'')+')', 'View':t.viewName||'', 'Records In':n(st.rows), 'Records Out':n(wc.written), 'Duration s':dur, 'Description':lines.join('\n'), 'Tally':JSON.stringify(Object.assign({}, st, { planned, written:wc.written, writeErrors:wc.writeErrors })), 'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id };
if(p.clientRecId) log['Client']=[p.clientRecId];
return [{ json:log }];
